#!/usr/bin/env bash
# B3b = B3a with ONE factor changed: + --sampler balanced --sampler_lang_balance --sampler_bona_frac 0.5 --ce_weights 0.3223 0.6777 (coupled sampler group; CE re-derived to keep the 0.1/0.9 effective class prior)
#   generated by exploop (wave B3, iteration 2) from exploop/B3/iter02/design.result.json
#  B3b = B3a + class- and language-balanced sampling: --sampler balanced --sampler_lang_balance
#    --sampler_bona_frac 0.5 --ce_weights 0.3223 0.6777. The four flags are one coupled group, and
#    the CE weights are re-derived from train_label.txt so the effective bona:spoof weight of
#    0.1/0.9 at 18.94 % bona (2.1028:1) is unchanged. Everything else is identical to B3a:
#    consistency js 0.3 with pairs=both, --batch_size 8 = 16 clips/step, 8 epochs, LR 2.5e-6 cosine
#    to 5e-7, loudness norm -23. The sampler draws len(dataset) items per epoch, so steps and the
#    schedule are unchanged (~8 h). Evidence (B3a report,
#    docs/experiments-exploration/b3-experiments/20261010_143058_B3a_*.md): English is 258 of 782
#    half_B noisy bona but 91 of 180 merge false alarms. English R_bona is 67.4 / 62.0 (matched /
#    heldout), against zh 84.7 / 81.3. English EER did not improve under consistency. The merge
#    operating point is already optimal (one global shift recovers 0.02), so the remaining error is
#    ranking, not calibration. Target: English bona exposure. Each English bona clip is drawn ~6.5x
#    per epoch; zh spoof drops to 0.40x. Rule against B3a-top5 = 93.06 on half_B: promote if the
#    delta is > +0.5, the CI excludes 0 and the clean drop is <= 0.5; null within +-0.5; negative
#    below -0.5.
#  Why: This targets the largest remaining error in the B3a report (§5.4, §7,
#    largest_remaining_error): confident noisy bona false alarms, half of them English. On the
#    half_B merge, English is 258 of 782 noisy bona but carries 91 of 180 false alarms. English
#    R_bona is 67.4 matched / 62.0 heldout, against zh 84.7 / 81.3. Full-set English EER did not
#    improve at the merge (matched 12.76 -> 13.66) and rose at ep8 on all three sets. The gap is
#    not new. The B2 wave summary says English bona recall never moved in that wave, and B3a's
#    consistency removed only 4 English false alarms (95 -> 91) against 29 Chinese ones (118 ->
#    89). The skill says that when a lever's target did not move, the next step should be a
#    different mechanism, not a higher dose. Consistency already hit heldout, matched and noisy
#    EER; it missed English and the saturated core. So I am trying the untested exposure mechanism
#    rather than --consistency_lambda 1.0 (analyst rank 2). The analyst ranked this lever first,
#    and it is in the wave.json lever_queue (sampler_balanced) and in the approved plan. Only the
#    English bona exposure should change, not the operating point. The B3a merge is already optimal
#    at 0.5 (best global logit -0.15, recoverable 0.02, report §5.2), so the CE weights are
#    re-derived from train_label.txt to keep the effective bona:spoof weight at 2.1028:1, as
#    lever_notes require. The four flags are one coupled group in wave.json, and every other B3a
#    flag is kept, including consistency js 0.3 at --batch_size 8. Run length is unchanged: 8
#    epochs, within max_epochs 10, and the same 75792 steps. A seed repeat is not warranted while
#    untested configuration levers that the evidence supports remain.
#  Hypothesis: The en-zh bona gap is an exposure problem. English bona are only 2,922 of 75,785
#    training clips (3.9 %), English is 23.2 % of training data, and P(bona|en)=0.1665 against
#    0.1965 for zh. Consistency cannot fix this, because the two views of an English bona clip
#    agree with each other while being wrong together. A class- and language-balanced draw (each
#    class half en / half zh, bona_frac 0.5) shows each English bona clip about 6.5x per epoch at
#    an unchanged effective class prior (CE 0.3223/0.6777). That should move English bona out of
#    the saturated spoof region and improve the ranking of English bona against spoof. Neither the
#    global operating point nor Chinese / clean behaviour should move.
#  Expected signature: Merge vs B3a-top5 (half_B WF1 93.06): - English: half_B English R_bona up by
#    at least 3 points on both matched and heldout (from 67.4 / 62.0). English noisy bona false
#    alarms fall below 91 of the 180. The English share at p_spoof >= 0.99 on matched falls below
#    26.4 %. Full-set merge English EER falls below 13.66 matched / 17.04 heldout. - Unchanged: zh
#    R_bona flat (84.7 / 81.3). Clean F1 within 0.5 of 97.48. Per-set R_spoof within about 0.5 of
#    99.38 matched / 99.06 heldout. The best global logit threshold stays near 0 (B3a merge -0.15),
#    not beyond +-1. - Training telemetry: the realised sampler shares in train.log are near bona
#    0.5 / en 0.5. Heldout carries most of the WF1 gain, so the merge half_B WF1 should end above
#    93.06.
#  Derivation: python3 -I on /mnt/paml-research/RTCFake/data/train_label.txt: cells {('en',
#    'bonafide'): 2922, ('zh', 'bonafide'): 11431, ('en', 'spoof'): 14632, ('zh', 'spoof'): 46800}
#    n 75785 bona 14353 spoof 61432 bona share 0.1894 effective bona:spoof weight ratio at 0.1/0.9
#    = 2.1028 ce_weights at bona_frac 0.5 (spoof,bona) = 0.3223 0.6777 check ratio 2.1028 en
#    P(bona|lang)=0.1665 lang share=0.2316 zh P(bona|lang)=0.1963 lang share=0.7684 ('en',
#    'bonafide') 2922 expected draws/epoch 18946 x per clip 6.48 vs shuffle 1.00 ('en', 'spoof')
#    14632 expected draws/epoch 18946 x per clip 1.29 vs shuffle 1.00 ('zh', 'bonafide') 11431
#    expected draws/epoch 18946 x per clip 1.66 vs shuffle 1.00 ('zh', 'spoof') 46800 expected
#    draws/epoch 18946 x per clip 0.40 vs shuffle 1.00 (Formula: ratio r = w_b*pi_b /
#    (w_s*(1-pi_b)) with 0.1/0.9 at pi_b=0.1894; at pi_b=0.5, w_b/w_s = r, so (w_s, w_b) =
#    (1/(1+r), r/(1+r)) = (0.3223, 0.6777). Order is [spoof, bonafide] per wave.json lever_notes.
#    The sampler draws len(dataset)=75785 items per epoch with replacement (b3wave/sampler.py), so
#    the step count (75792 with --batch_size 8 pairs) and the cosine schedule are unchanged.)
#  Eval note: Evaluate both readouts (top-5 merge = objective, epoch_8) with --loudness_norm
#    --loudness_norm_lufs -23; checkpoints are plain ModelSLS state_dicts. Compare against B3a-top5
#    / B3a-ep8 (current best) and the fixed comparators B2f-top5 / B2f-ep8. Report half_B English
#    vs Chinese R_bona per set, the English share at p_spoof >= 0.99, full-set lang-en EER from the
#    breakdowns, per-set R_spoof (spoof under-exposure check) and the best global logit threshold
#    (prior check). Check the per-epoch 'sampler bona=… en=…' telemetry in train.log.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B3a merge (93.06) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. Wave rule against B3a-top5 = 93.06 on half_B: - Promote /
#    positive: delta merge > +0.5, the paired-bootstrap CI excluding 0, and a clean F1 drop of at
#    most 0.5. - Null: delta within +-0.5. - Negative: delta below -0.5. Mechanism-level
#    refutations: - Exposure is not the cause (null on the mechanism): delta within +-0.5 AND
#    half_B English R_bona within +-3 on both matched and heldout. - The prior derivation failed:
#    the best global logit threshold moves beyond +-1, or the clean F1 drop exceeds 0.5. - Spoof
#    under-exposure costs more than the English gain: R_spoof falls by more than 0.5 on matched or
#    heldout (zh spoof is drawn only 0.40x per clip per epoch). - The repeated English bona draws
#    over-fit: epoch-8 dev loss above B3a's 0.1722, together with English R_bona not up.
#
#   bash scripts/run_B3b.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B3b.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B3b.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B3b_qwen17_rtc_musan_loud23_cos8_lr2.5e6_cjs03_sampbal_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 8
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --consistency js
    --consistency_lambda 0.3
    --consistency_pairs both
    --sampler balanced
    --sampler_lang_balance
    --sampler_bona_frac 0.5
    --ce_weights 0.3223 0.6777
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b3wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
